-- Additive migration; do not delete legacy sessions, tasks, files, grants or menus.
CREATE TABLE IF NOT EXISTS workspace_registry (
 id VARCHAR(64) PRIMARY KEY, status VARCHAR(32) NOT NULL,
 access_permission_code VARCHAR(128) NOT NULL, manifest_json LONGTEXT NOT NULL,
 default_workspace BOOLEAN NOT NULL DEFAULT false, version BIGINT DEFAULT 0,
 created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL
);
CREATE TABLE IF NOT EXISTS workspace_user_preference (
 id VARCHAR(64) PRIMARY KEY, tenant_id VARCHAR(64) NOT NULL, user_id VARCHAR(64) NOT NULL,
 default_workspace_id VARCHAR(64), last_workspace_id VARCHAR(64), version BIGINT DEFAULT 0,
 created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL,
 CONSTRAINT uk_workspace_preference_user UNIQUE (tenant_id, user_id)
);
CREATE TABLE IF NOT EXISTS workspace_resource_origin (
 id VARCHAR(64) PRIMARY KEY, tenant_id VARCHAR(64) NOT NULL,
 resource_type VARCHAR(32) NOT NULL, resource_id VARCHAR(128) NOT NULL,
 workspace_id VARCHAR(64) NOT NULL, creator_user_id VARCHAR(64) NOT NULL,
 created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL,
 CONSTRAINT uk_workspace_origin_resource UNIQUE (tenant_id, resource_type, resource_id)
);

-- Workspace application configuration. No Runtime tool, Skill or resource grants.

INSERT INTO workspace_registry (id, status, access_permission_code, manifest_json, default_workspace, version, created_at, updated_at) SELECT 'zhice', 'enabled', 'workspace:zhice:access', '{"schemaVersion":"workspace-manifest.v1","configVersion":1,"workspaceId":"zhice","appVersion":"1.0.0","name":"灵动智策","icon":"layout-dashboard","description":"智能对话、知识检索与系统管理","entryPage":"chat","layoutType":"assistant","pages":[{"id":"chat","menuCode":"chat","componentKey":"chat","props":{}},{"id":"search","menuCode":"search","componentKey":"search","props":{}},{"id":"domainAnalysis","menuCode":"domainAnalysis","componentKey":"domainAnalysis","props":{}},{"id":"market","menuCode":"market","componentKey":"market","props":{}},{"id":"favorites","menuCode":"favorites","componentKey":"favorites","props":{}},{"id":"library","menuCode":"library","componentKey":"library","props":{}},{"id":"mcp","menuCode":"mcp","componentKey":"mcp","props":{}},{"id":"dataScience","menuCode":"dataScience","componentKey":"dataScience","props":{}},{"id":"dataScienceEnvironment","menuCode":"dataScienceEnvironment","componentKey":"dataScienceEnvironment","props":{}},{"id":"dataScienceDevelop","menuCode":"dataScienceDevelop","componentKey":"dataScienceDevelop","props":{}},{"id":"dataScienceData","menuCode":"dataScienceData","componentKey":"dataScienceData","props":{}},{"id":"dataScienceScripts","menuCode":"dataScienceScripts","componentKey":"dataScienceScripts","props":{}},{"id":"dataScienceSkills","menuCode":"dataScienceSkills","componentKey":"dataScienceSkills","props":{}},{"id":"agents","menuCode":"agents","componentKey":"agents","props":{}},{"id":"schedules","menuCode":"schedules","componentKey":"schedules","props":{}},{"id":"rules","menuCode":"rules","componentKey":"rules","props":{}},{"id":"debugger","menuCode":"debugger","componentKey":"debugger","props":{}},{"id":"tasks","menuCode":"tasks","componentKey":"tasks","props":{}},{"id":"system","menuCode":"system","componentKey":"system","props":{}},{"id":"systemUsers","menuCode":"systemUsers","componentKey":"systemUsers","props":{}},{"id":"systemOrganizations","menuCode":"systemOrganizations","componentKey":"systemOrganizations","props":{}},{"id":"systemRoles","menuCode":"systemRoles","componentKey":"systemRoles","props":{}},{"id":"systemLogins","menuCode":"systemLogins","componentKey":"systemLogins","props":{}},{"id":"systemResources","menuCode":"systemResources","componentKey":"systemResources","props":{}},{"id":"systemSkillRoles","menuCode":"systemSkillRoles","componentKey":"systemSkillRoles","props":{}},{"id":"models","menuCode":"models","componentKey":"models","props":{}}],"requiredCapabilities":[],"optionalCapabilities":[],"defaultSkillIds":[]}', true, 0, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM workspace_registry WHERE id = 'zhice');

INSERT INTO workspace_registry (id, status, access_permission_code, manifest_json, default_workspace, version, created_at, updated_at) SELECT 'data-science', 'enabled', 'capability:data-science', '{"schemaVersion":"workspace-manifest.v1","configVersion":1,"workspaceId":"data-science","appVersion":"1.0.0","name":"数据科学","icon":"flask","description":"Python 环境、开发、数据、脚本与领域 Skills","entryPage":"dataScienceEnvironment","layoutType":"studio","pages":[{"id":"dataScience","menuCode":"dataScience","componentKey":"dataScience","props":{}},{"id":"dataScienceEnvironment","menuCode":"dataScienceEnvironment","componentKey":"dataScienceEnvironment","props":{}},{"id":"dataScienceDevelop","menuCode":"dataScienceDevelop","componentKey":"dataScienceDevelop","props":{}},{"id":"dataScienceData","menuCode":"dataScienceData","componentKey":"dataScienceData","props":{}},{"id":"dataScienceScripts","menuCode":"dataScienceScripts","componentKey":"dataScienceScripts","props":{}},{"id":"dataScienceSkills","menuCode":"dataScienceSkills","componentKey":"dataScienceSkills","props":{}}],"requiredCapabilities":["capability:data-science"],"optionalCapabilities":[{"id":"sql.generation","state":"reserved","name":"SQL Studio"}],"defaultSkillIds":[]}', false, 0, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM workspace_registry WHERE id = 'data-science');

INSERT INTO sys_permission (id, permission_code, permission_name, permission_type, resource_path, http_method, status, sort_order, created_at, updated_at) SELECT 'ws-api', 'workspace:api:access', 'Workspace access', 'api', '/api/v1/workspaces/**', '*', 'enabled', 0, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM sys_permission WHERE permission_code = 'workspace:api:access');

INSERT INTO sys_permission (id, permission_code, permission_name, permission_type, resource_path, http_method, status, sort_order, created_at, updated_at) SELECT 'ws-zhice', 'workspace:zhice:access', 'Zhice access', 'menu', NULL, NULL, 'enabled', 0, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM sys_permission WHERE permission_code = 'workspace:zhice:access');

INSERT INTO sys_permission (id, permission_code, permission_name, permission_type, resource_path, http_method, status, sort_order, created_at, updated_at) SELECT 'ws-manage', 'system:workspaces:manage', 'Workspace management', 'api', '/api/v1/enterprise/workspaces/**', '*', 'enabled', 0, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM sys_permission WHERE permission_code = 'system:workspaces:manage');

INSERT INTO sys_role_permission (id, tenant_id, role_id, permission_id, created_at, updated_at) SELECT MD5(CONCAT('wsa-', r.id)), r.tenant_id, r.id, target.id, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM sys_role r JOIN sys_permission target ON target.permission_code = 'workspace:api:access' WHERE r.status = 'enabled' AND EXISTS (SELECT 1 FROM sys_role_permission rp JOIN sys_permission p ON p.id = rp.permission_id WHERE rp.role_id = r.id AND rp.tenant_id = r.tenant_id AND p.status = 'enabled' AND p.permission_code = 'account:menus:read') AND NOT EXISTS (SELECT 1 FROM sys_role_permission existing WHERE existing.role_id = r.id AND existing.permission_id = target.id) AND NOT EXISTS (SELECT 1 FROM sys_permission WHERE permission_code = 'system:workspace-compatibility:v1');

INSERT INTO sys_role_permission (id, tenant_id, role_id, permission_id, created_at, updated_at) SELECT MD5(CONCAT('wsz-', r.id)), r.tenant_id, r.id, target.id, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM sys_role r JOIN sys_permission target ON target.permission_code = 'workspace:zhice:access' WHERE r.status = 'enabled' AND EXISTS (SELECT 1 FROM sys_role_permission rp JOIN sys_permission p ON p.id = rp.permission_id WHERE rp.role_id = r.id AND rp.tenant_id = r.tenant_id AND p.status = 'enabled' AND EXISTS (SELECT 1 FROM sys_menu_permission mp JOIN sys_menu m ON m.id = mp.menu_id WHERE mp.permission_id = p.id AND m.status = 'enabled')) AND NOT EXISTS (SELECT 1 FROM sys_role_permission existing WHERE existing.role_id = r.id AND existing.permission_id = target.id) AND NOT EXISTS (SELECT 1 FROM sys_permission WHERE permission_code = 'system:workspace-compatibility:v1');

INSERT INTO sys_role_permission (id, tenant_id, role_id, permission_id, created_at, updated_at) SELECT MD5(CONCAT('wsm-', r.id)), r.tenant_id, r.id, target.id, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP FROM sys_role r JOIN sys_permission target ON target.permission_code = 'system:workspaces:manage' WHERE r.status = 'enabled' AND EXISTS (SELECT 1 FROM sys_role_permission rp JOIN sys_permission p ON p.id = rp.permission_id WHERE rp.role_id = r.id AND rp.tenant_id = r.tenant_id AND p.status = 'enabled' AND r.role_code = 'SUPER_ADMIN' AND p.permission_code = 'system:role:authorize') AND NOT EXISTS (SELECT 1 FROM sys_role_permission existing WHERE existing.role_id = r.id AND existing.permission_id = target.id) AND NOT EXISTS (SELECT 1 FROM sys_permission WHERE permission_code = 'system:workspace-compatibility:v1');

INSERT INTO sys_permission (id, permission_code, permission_name, permission_type, status, sort_order, created_at, updated_at) SELECT 'ws-marker', 'system:workspace-compatibility:v1', 'Workspace compatibility migration V1', 'internal', 'enabled', 0, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP WHERE NOT EXISTS (SELECT 1 FROM sys_permission WHERE permission_code = 'system:workspace-compatibility:v1');
